-- Frozen from the real version-1 Drift database and repositories, not hand-written DDL.
BEGIN TRANSACTION;
CREATE TABLE "cooked_adjustments" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "meal_plan_entry_id" INTEGER NOT NULL REFERENCES meal_plan_entries (id) ON DELETE CASCADE, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "amount_deducted" REAL NOT NULL, "unit" TEXT NOT NULL, "previous_last_used_at" TEXT NULL, "created_at" TEXT NOT NULL);
CREATE TABLE "ingredient_categories" ("category" TEXT NOT NULL, "food_group" TEXT NOT NULL, "shelf_life_days" INTEGER NOT NULL, PRIMARY KEY ("category"));
CREATE TABLE "ingredients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "canonical_name" TEXT NOT NULL UNIQUE, "api_ingredient_id" TEXT NULL, "api_name" TEXT NULL, "category" TEXT NULL REFERENCES ingredient_categories (category), "canonical_unit" TEXT NULL, "is_staple" INTEGER NOT NULL DEFAULT 0 CHECK ("is_staple" IN (0, 1)));
CREATE TABLE "meal_plan_entries" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "recipe_id" INTEGER NULL REFERENCES recipes (id) ON DELETE SET NULL, "recipe_title" TEXT NOT NULL, "planned_date" TEXT NOT NULL, "cooked_at" TEXT NULL, "servings" INTEGER NOT NULL);
CREATE TABLE "pantry_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "quantity" REAL NOT NULL, "unit" TEXT NOT NULL, "unit_price" REAL NULL, "expiry_date" TEXT NULL, "last_used_at" TEXT NULL, "updated_at" TEXT NOT NULL, UNIQUE ("user_id", "ingredient_id"));
CREATE TABLE "recipe_dietary_flags" ("recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "flag" TEXT NOT NULL, PRIMARY KEY ("recipe_id", "flag"));
CREATE TABLE "recipe_ingredients" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "recipe_id" INTEGER NOT NULL REFERENCES recipes (id) ON DELETE CASCADE, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "quantity" REAL NOT NULL, "unit" TEXT NOT NULL, "preparation" TEXT NULL, "is_optional" INTEGER NOT NULL DEFAULT 0 CHECK ("is_optional" IN (0, 1)), "substitutions" TEXT NOT NULL DEFAULT '[]');
CREATE TABLE "recipes" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "external_id" TEXT NULL, "title" TEXT NOT NULL, "source_url" TEXT NULL, "cuisine" TEXT NULL, "difficulty" TEXT NULL, "active_time_mins" INTEGER NULL, "total_time_mins" INTEGER NULL, "not_suitable_for" TEXT NOT NULL DEFAULT '[]', "yield_count" INTEGER NULL, "nutrition" TEXT NULL, "instructions" TEXT NOT NULL DEFAULT '[]', "last_cooked_at" TEXT NULL, UNIQUE ("user_id", "external_id"));
CREATE TABLE "shopping_list_items" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" TEXT NOT NULL, "ingredient_id" INTEGER NOT NULL REFERENCES ingredients (id), "name" TEXT NOT NULL, "quantity" REAL NULL, "unit" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "is_checked" INTEGER NOT NULL DEFAULT 0 CHECK ("is_checked" IN (0, 1)), "source_meal_plan_entry_id" INTEGER NULL REFERENCES meal_plan_entries (id) ON DELETE CASCADE);
CREATE TABLE "user_config" ("id" TEXT NOT NULL, "purchase_tolerance" REAL NOT NULL DEFAULT 0.5, "preferred_servings" INTEGER NOT NULL DEFAULT 2, "meals_per_week" INTEGER NOT NULL DEFAULT 5, "dietary_flags" TEXT NOT NULL DEFAULT '[]', "max_active_time_mins" INTEGER NULL, "onboarding_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("onboarding_completed" IN (0, 1)), PRIMARY KEY ("id"));
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA user_version = 1;
